import pandas as pd

def process_csv(file_path, operations):
    # Load the CSV file into a DataFrame
    df = pd.read_csv(file_path)

    # Apply each operation provided by the user
    for operation, args in operations.items():
        if operation == 'rename':
            df.rename(columns=args['columns'], inplace=True)
        elif operation == 'filter':
            conditions = args['conditions']
            for condition, value in conditions.items():
                df = df[df[condition] == value]
        elif operation == 'add_column':
            df[args['name']] = args['expression']
        else:
            raise ValueError(f"Unsupported operation: {operation}")

    # Return the transformed DataFrame
    return df
