app.config['UPLOAD_FOLDER'] = UPLOAD_FOLDER

if not os.path.exists(UPLOAD_FOLDER):
    os.makedirs(UPLOAD_FOLDER)

def save_photo(photo, caption):
    filename = photo.filename
    filepath = os.path.join(app.config['UPLOAD_FOLDER'], filename)
    photo.save(filepath)

    with open(os.path.join(UPLOAD_FOLDER, f"{filename}.txt"), "w") as file:
        file.write(caption)

@app.route("/upload", methods=["POST"])
def upload():
    photo = request.files.get("photo")
    caption = request.form.get("caption")
    if photo and allowed_file(photo.filename):
        save_photo(photo, caption)
        msg = "<p>Thanks for sharing your photo and caption!</p>"
    else:
        msg = "<p>Invalid file type. Please upload a photo.</p>"
    return msg

def allowed_file(filename):
    ALLOWED_EXTENSIONS = {'png', 'jpg', 'jpeg', 'gif'}
    return '.' in filename and \
           filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

@app.route('/uploads/<filename>')
def uploaded_file(filename):
    return send_from_directory(app.config['UPLOAD_FOLDER'], filename)

if __name__ == "__main__":
    app.run(debug=True)
