shared_storage = []

def simulate_log_source(source_id):
    while True:
        # Simulate receiving a log entry
        log_entry = f"Log Entry from Source {source_id} at {time.strftime('%Y-%m-%d %H:%M:%S')}"
        print(log_entry)
        yield log_entry
        time.sleep(1)

def write_to_storage(log_entries, storage):
    for entry in log_entries:
        with open(storage, 'a') as file:
            file.write(entry + '\n')
            print(f"Wrote to storage: {entry}")

def main():
    num_sources = 3
    storage_path = 'logs.txt'

    with concurrent.futures.ThreadPoolExecutor() as executor:
        futures = [executor.submit(write_to_storage, simulate_log_source(i), storage_path) for i in range(num_sources)]

        for future in concurrent.futures.as_completed(futures):
            try:
                future.result()
            except Exception as e:
                print(f"Error during logging: {e}")

if __name__ == "__main__":
