import argparse
import os
from typing import List

def calculate_comment_density(file_path: str) -> float:
    total_lines = 0
    comment_lines = 0

    with open(file_path, 'r', encoding='utf-8') as file:
        lines = file.readlines()

        for line in lines:
            stripped_line = line.strip()
            if stripped_line.startswith('#'):
                comment_lines += 1
            total_lines += 1

    if total_lines == 0:
        return 0.0

    return (comment_lines / total_lines) * 100

def analyze_files(file_paths: List[str], output_file: str, permissions: str):
    results = {}

    for file_path in file_paths:
        if not os.path.isfile(file_path):
            print(f"Skipping non-existent file: {file_path}")
            continue

        try:
            comment_density = calculate_comment_density(file_path)
            results[file_path] = comment_density
            print(f"{file_path}: Comment Density = {comment_density:.2f}%")
        except Exception as e:
            print(f"Error analyzing file {file_path}: {e}")

    if output_file:
        with open(output_file, 'w', encoding='utf-8') as out_file:
            for file_path, density in results.items():
                out_file.write(f"{file_path}: Comment Density = {density:.2f}%\n")

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Code Comment Analyzer")
    parser.add_argument('files', metavar='FILE', type=str, nargs='+',
                        help='list of files to analyze')
    parser.add_argument('-o', '--output', dest='output_file', type=str,
                        help='write report to a file')
    parser.add_argument('-p', '--permissions', dest='permissions', type=str,
                        default='644',
                        help='set permissions for the output file (default: 644)')

    args = parser.parse_args()

    if args.output_file:
        try:
            os.chmod(args.output_file, int(args.permissions, 8))
        except ValueError:
            print(f"Invalid permission value: {args.permissions}")
            exit(1)

    analyze_files(args.files, args.output_file, args.permissions)
