import os
import argparse
from collections import defaultdict

def calculate_comment_density(file_path):
    total_lines = 0
    comment_lines = 0

    with open(file_path, 'r', encoding='utf-8') as file:
        for line in file:
            total_lines += 1
            if line.strip().startswith('#'):
                comment_lines += 1

    if total_lines == 0:
        return 0.0

    return (comment_lines / total_lines) * 100

def analyze_code_directory(directory):
    results = defaultdict(list)

    for root, _, files in os.walk(directory):
        for file in files:
            if file.endswith(('.py')):
                file_path = os.path.join(root, file)
                density = calculate_comment_density(file_path)
                results[directory].append((file, density))

    return results

def generate_report(results, output_file=None):
    header = "File\tComment Density\n"
    report = header + "\n".join([f"{file}\t{density:.2f}%" for directory, items in results.items() for file, density in items])

    if output_file:
        with open(output_file, 'w', encoding='utf-8') as f:
            f.write(report)
    else:
        print(report)

def main():
    parser = argparse.ArgumentParser(description="Code Comment Density Analyzer")
    parser.add_argument("directory", help="The directory containing the Python files to analyze")
    parser.add_argument("-o", "--output", help="Output the report to a specified file instead of printing it")
    args = parser.parse_args()

    results = analyze_code_directory(args.directory)
    generate_report(results, args.output)

if __name__ == "__main__":
    main()
