import os
from tkinter import Tk, filedialog, simpledialog

def get_filenames(directory):
    filenames = []
    for filename in os.listdir(directory):
        if os.path.isfile(os.path.join(directory, filename)):
            filenames.append(filename)
    return filenames

def rename_files(filenames, directory, new_pattern):
    for i, old_filename in enumerate(filenames):
        new_filename = new_pattern.format(i+1, old_filename)
        os.rename(os.path.join(directory, old_filename), os.path.join(directory, new_filename))

def main():
    root = Tk()
    root.withdraw()  # Hides the main window

    directory = filedialog.askdirectory(title="Select a directory")
    if not directory:
        print("No directory selected.")
        return

    filenames = get_filenames(directory)

    pattern = simpledialog.askstring("Input", "Enter new file name pattern (e.g., 'new_file_{0:02d}_{1}'):")
    if not pattern:
        print("No pattern entered.")
        return

    rename_files(filenames, directory, pattern)
    print("Files renamed successfully.")

if __name__ == "__main__":
    main()
