app = Flask(__name__)

def create_tarball(directory, output_file):
    try:
        # Run the tar command to create a tarball
        subprocess.run(['tar', '-czf', output_file, '-C', directory, '.'], check=True)
        return True
    except subprocess.CalledProcessError as e:
        print(f"Failed to create tarball: {e}")
        return False

@app.route('/release', methods=['POST'])
def release():
    data = request.json
    if 'directory' not in data or 'output_file' not in data:
        return jsonify({'error': 'Missing required parameters'}), 400

    directory = data['directory']
    output_file = data['output_file']

    if not os.path.exists(directory):
        return jsonify({'error': f'Directory {directory} does not exist'}), 404

    success = create_tarball(directory, output_file)

    if success:
        return jsonify({'message': f'Tarball created successfully at {output_file}'})
    else:
        return jsonify({'error': 'Failed to create tarball'}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
