def upload_file():
    f = request.files['file']

    if len(request.files) == 0:
        return 'No file uploaded'

    if not f.filename.endswith('.dxf'):
        return 'Invalid file type. Please upload a DXF file.'

    filename = f.filename
    filepath = os.path.join(app.config['UPLOAD_FOLDER'], filename)

    f.save(filepath)

    try:
        dxf = readfile(filepath)
        entities = dxf.entities
        total_length = sum(entity.length for entity in entities if hasattr(entity, 'length'))
        max_point = max((entity.extents[1] for entity in entities if hasattr(entity, 'extents')), default=(0, 0))

        return {
            'total_length': total_length,
            'max_point': max_point.tolist()
        }
    except Exception as e:
        return str(e), 500

if __name__ == '__main__':
    app.run(debug=True)
