import subprocess
import os

def run_rsync(source, destination):
    rsync_command = f"rsync -avz {source} {destination}"
    try:
        result = subprocess.run(rsync_command, shell=True, check=True)
        print(f"Successfully synchronized {source} to {destination}")
    except subprocess.CalledProcessError as e:
        print(f"Failed to synchronize: {e}")

def synchronize_files(sources, destination):
    if not os.path.exists(destination):
        os.makedirs(destination)

    for source in sources:
        if os.path.exists(source):
            run_rsync(source, destination)
        else:
            print(f"Source directory {source} does not exist.")

if __name__ == "__main__":
    # List of source directories to synchronize
    sources = [
        "/path/to/source1/",
        "/path/to/source2/"
    ]

    # Destination directory where files will be synchronized
    destination = "/path/to/destination/"

    synchronize_files(sources, destination)
