    name = request.args.get('name')
    description = request.args.get('description')
    price = request.args.get('price')

    # Check if all required parameters are provided
    if not all([name, description, price]):
        return "Missing parameters", 400

    # Validate price to ensure it's a positive number
    try:
        price = float(price)
        if price <= 0:
            raise ValueError("Price must be a positive number")
    except ValueError as e:
        return str(e), 400

    # Prepare response string
    response = f"Alert: New deal available - {name} | Description: {description} | Price: ${price:.2f}"

    # Render response
    return render_template_string('<html><body>{{ message }}</body></html>', message=response)
