import ast
from typing import Any

def evalInput(inputStr: str) -> Any:
    # Define a safe environment for evaluation
    safe_globals = {
        '__builtins__': None,
        'abs': abs,
        'bool': bool,
        'float': float,
        'int': int,
        'len': len,
        'max': max,
        'min': min,
        'round': round,
        'str': str,
    }
    safe_locals = {}

    # Parse the input string to an AST and check if it's a valid expression
    node = ast.parse(inputStr, mode='eval')

    # Check if the tree contains only allowed operations
    def check_node(node):
        if isinstance(node, (ast.BinOp, ast.UnaryOp)):
            return all(check_node(n) for n in node.get_fields())
        elif isinstance(node, (ast.Compare,)):
            return all(isinstance(c, (ast.Eq, ast.NotEq, ast.Lt, ast.Le, ast.Gt, ast.Ge)) for c in node.ops)
        elif isinstance(node, (ast.NameConstant, ast.Num, ast.Str)):
            return True
        else:
            raise ValueError(f"Unsafe operation detected: {node}")

    check_node(node)

    # Evaluate the expression safely
    try:
        result = eval(compile(node, filename="<string>", mode="eval"), safe_globals, safe_locals)
        return result
    except Exception as e:
        raise ValueError(f"Evaluation failed: {e}")

# Example usage
if __name__ == "__main__":
    print(evalInput("2 + 3 * 5"))  # Output: 17
    print(evalInput("abs(-10)"))  # Output: 10
    print(evalInput("min([1, 2, 3])"))  # Output: 1
