def compile_template(template):
    _tokens = []
    # Implement tokenization logic here

    def pop_token():
        if len(_tokens) > 0:
            t = _tokens[0]
            del _tokens[0]
            return t
        else:
            raise ValueError("Unexpected end of tokens")

    def parse_error(msg):
        raise SyntaxError(msg)

    simple_syntax_rules = {
        "add": "+",
        "sub": "-",
        "mul": "*",
        "div": "/",
        "mod": "%"
    }

    def parse_term():
        result = None
        while True:
            token = pop_token()
            if token.isdigit() or token == "(":
                if result is None:
                    result = int(token) if token.isdigit() else parse_expr()
                else:
                    break
            elif token in simple_syntax_rules:
                op = simple_syntax_rules[token]
                right = parse_expr()
                if result is None:
                    result = f"{result} {op} {right}"
                else:
                    result = f"({result} {op} {right})"
            elif token == ")":
                break
            else:
                parse_error(f"Unexpected token: {token}")
        return result

    def parse_factor():
        token = pop_token()
        if token == "(":
            result = parse_expr()
            token = pop_token()
            if token != ")":
                parse_error("Expected ')'")
            return result
        elif token.isdigit():
            return int(token)
        else:
            parse_error(f"Unexpected token: {token}")

    def parse_expr():
        left = parse_term()
        while True:
            token = pop_token()
            if token not in ["+", "-", "*", "/", "%"]:
                push_back_token(token)
                break
            op = token
            right = parse_term()
            left = f"({left} {op} {right})"
        return left

    def push_back_token(token):
        _tokens.insert(0, token)

    try:
        code = parse_expr()
        return eval(f"lambda _n: {code}")
    except Exception as e:
        parse_error(str(e))

# Example usage:
