import types

def update_function(params, func):
    # Create a new function using the original's code and globals
    new_func = types.FunctionType(func.__code__, globals(), func.__name__)

    # Update the function's default arguments if provided
    if params:
        defaults = func.__defaults__
        if defaults:
            defaults = list(defaults)
        else:
            defaults = []

        for param, value in params.items():
            if hasattr(new_func, param) and not getattr(new_func, param).__call__:
                setattr(new_func, param, value)
                if defaults and param in defaults:
                    defaults.remove(param)
        if defaults:
            new_func.__defaults__ = tuple(defaults)
        else:
            delattr(new_func, '__defaults__')

    # Set the updated function's repr method
    def new_repr(self):
        return f"{self.__class__.__name__}({params})"
    new_func.__repr__ = types.MethodType(new_repr, new_func)

    return new_func
