    birthday_list = [bd.strip() for bd in birthday_data.split(',')]

    today = datetime.date.today()
    upcoming_birthdays = []

    for bd in birthday_list:
        try:
            name, birthdate_str = bd.split(':')
            birthdate = datetime.datetime.strptime(birthdate_str.strip(), '%m-%d').date().replace(year=today.year)
            if birthdate >= today:
                days_until = (birthdate - today).days
                upcoming_birthdays.append((name.strip(), days_until))
        except ValueError:
