            print("Not connected to remote host.")
            return

        try:
            directory, filename = os.path.split(remote_path)
            self.sftp_client.put(local_path, remote_path)
            print(f"File '{filename}' backed up successfully to '{remote_path}'.")
        except Exception as e:
            print(f"Failed to backup file: {e}")

    def backup_directory(self, local_dir, remote_dir):
        if not self.sftp_client:
            print("Not connected to remote host.")
            return

        try:
            if not self.sftp_client.exists(remote_dir):
                self.sftp_client.mkdir(remote_dir)

            for root, dirs, files in os.walk(local_dir):
                for name in files:
                    local_path = os.path.join(root, name)
                    relative_path = os.path.relpath(local_path, local_dir)
                    remote_path = os.path.join(remote_dir, relative_path)
                    self.backup_file(local_path, remote_path)
            print("Directory backed up successfully.")
        except Exception as e:
            print(f"Failed to backup directory: {e}")
