import os
import pathlib
import shutil
from typing import List, Dict

class FileSynchronizer:
    def __init__(self, source_dir: str, destination_dir: str):
        self.source_dir = pathlib.Path(source_dir)
        self.destination_dir = pathlib.Path(destination_dir)

    def sync_files(self, files: List[str] = None) -> None:
        if not files:
            files = self.get_files(self.source_dir)
        for file in files:
            source_file = self.source_dir / file
            destination_file = self.destination_dir / file
            self._copy_file(source_file, destination_file, overwrite=True)

    def get_files(self, dir: pathlib.Path) -> List[str]:
        return [f for f in dir.glob('*') if f.is_file()]

    def _copy_file(self, source: pathlib.Path, destination: pathlib.Path, overwrite: bool) -> None:
        if destination.exists() and not overwrite:
            print(f"File {destination} already exists, skipping.")
        else:
            shutil.copy2(source, destination)

    def _delete_unwanted_files(self) -> None:
        files_to_delete = [f for f in self.destination_dir.glob('*')
                          if not self.source_dir.glob(f.name)]
        for file in files_to_delete:
            if file.is_file():
                os.remove(file)


def main() -> None:
    source_dir = '/path/to/source/directory'
    destination_dir = '/path/to/destination/directory'

    synchronizer = FileSynchronizer(source_dir, destination_dir)
    synchronizer.sync_files()
    synchronizer._delete_unwanted_files()


if __name__ == '__main__':
    main()
