def sync_folders(source, destination):
    if not os.path.exists(destination):
        os.makedirs(destination)
    files = os.listdir(source)
    for f in files:
        source_path = os.path.join(source, f)
        dest_path = os.path.join(destination, f)

        if os.path.isfile(source_path):
            if os.path.exists(dest_path):
                remote_permission = get_remote_permission(source_path)
                if remote_permission == None:
                    shutil.copyfile(source_path, dest_path)
                    set_remote_permission(source_path, remote_permission)
                elif stat.S_IMODE(os.stat(source_path).st_mode) == remote_permission:
                    continue
                elif remote_permission > stat.S_IMODE(os.stat(source_path).st_mode):
                    shutil.copyfile(source_path, dest_path)
                    set_remote_permission(source_path, remote_permission)
                else:
                    os.remove(dest_path)
                    shutil.copyfile(source_path, dest_path)
                    set_remote_permission(source_path, remote_permission)
            else:
                shutil.copyfile(source_path, dest_path)
                set_remote_permission(source_path, remote_permission)

        elif os.path.isdir(source_path):
            sync_folders(source_path, os.path.join(destination, f))

def get_remote_permission(file_path):
    try:
        transport = paramiko.Transport((socket.gethostbyname('remote_server'), 22))
        transport.connect(username = getpass.getuser(), password = getpass.getpass())
        sftp = paramiko.SFTPClient.from_transport(transport)
        return stat.S_IMODE(sftp.stat(file_path).st_mode)
    except Exception as e:
        print(f"Failed to get remote permission: {e}")
        return None

def set_remote_permission(file_path, permission):
