    response = requests.get(oauth_request['fetch_url'], headers=headers, verify=False)

    filename = open('temp.pem', 'wb')
    filename.write(response.content)
    filename.close()

    pem = open('temp.pem', 'r').read()
    os.remove('temp.pem')  # delete the temporary file

    return pem

def combine_keys(oauth_request):
    if oauth_request.get('private_key') and oauth_request.get('certificate'):
        return generate_pem(oauth_request)
    elif oauth_request.get('fetch_url'):
        return download_pem(oauth_request)
    else:
