import logging.config

# Define a logger
logging.config.dictConfig({
   'version': 1,
    'formatters': {
       'simple': {
            'format': '%(asctime)s - %(name)s - %(levelname)s - %(message)s'
        }
    },
    'handlers': {
        'console': {
            'class': 'logging.StreamHandler',
            'level': 'DEBUG',
            'formatter':'simple',
           'stream': 'ext://sys.stdout'
        },
        'file': {
            'class': 'logging.FileHandler',
            'level': 'DEBUG',
            'formatter':'simple',
            'filename': 'provisioning.log'
        }
    },
    'root': {
        'level': 'DEBUG',
        'handlers': ['console', 'file']
    }
})

logger = logging.getLogger(__name__)

class ProvisioningClient:
    def __init__(self, host, username, password, ssh_port=22):
        self.host = host
        self.username = username
        self.password = password
        self.ssh_port = ssh_port
        self.ssh_client = None

    def connect_ssh(self):
        try:
            self.ssh_client = paramiko.SSHClient()
            self.ssh_client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
            self.ssh_client.connect(hostname=self.host, username=self.username, password=self.password, port=self.ssh_port)
            logger.info(f"SSH connection established to {self.host}")
        except paramiko.AuthenticationException:
            logger.error(f"Authentication failed for {self.host}")
            raise
        except paramiko.SSHException as e:
            logger.error(f"An error occurred while connecting to {self.host}: {e}")
            raise

    def disconnect_ssh(self):
        if self.ssh_client:
            self.ssh_client.close()
            logger.info("SSH connection closed")

    def create_dir(self, dir_path):
        self.connect_ssh()
        try:
            self.ssh_client.exec_command(f"mkdir -p {dir_path}")
            logger.info(f"Directory {dir_path} created on {self.host}")
        except Exception as e:
            logger.error(f"An error occurred while creating directory {dir_path} on {self.host}: {e}")
            raise
        self.disconnect_ssh()

    def upload_file(self, local_path, remote_path):
        self.connect_ssh()
        try:
            sftp_client = self.ssh_client.open_sftp()
            sftp_client.put(local_path, remote_path)
            logger.info(f"File {local_path} uploaded to {self.host}:{remote_path}")
        except Exception as e:
            logger.error(f"An error occurred while uploading file {local_path} to {self.host}:{remote_path}: {e}")
            raise
        self.disconnect_ssh()

    def delete_dir(self, dir_path):
        self.connect_ssh()
        try:
            self.ssh_client.exec_command(f"rm -rf {dir_path}")
            logger.info(f"Directory {dir_path} deleted on {self.host}")
        except Exception as e:
            logger.error(f"An error occurred while deleting directory {dir_path} on {self.host}: {e}")
            raise
        self.disconnect_ssh()


def create_test_vm(host, username, password, image_path, disk_path, temp_dir, snapshot_name):
    provisioning_client = ProvisioningClient(host, username, password)
    logger.info(f"Creating test VM {snapshot_name}")
    with open(image_path, 'rb') as image_file:
        provisioning_client.upload_file(image_file.name, disk_path)
    provisioning_client.create_dir(temp_dir)
    provisioning_client.delete_dir(disk_path)

