    def create_backup(self, directory):
        filename = self.generate_backup_filename(directory)
        if not os.path.exists(directory):
            logging.error("Source directory does not exist")
            return False

        with tarfile.open(filename, "w:gz") as tar:
            tar.add(directory, arcname=os.path.basename(directory))

        return filename

    def send_backup(self, filename):
        try:
            self.sftp_client.put(filename, f"{self.destination_path}/{filename}")
            return True
        except Exception as e:
            logging.error(f"Error sending file: {e}")
            return False

    def close_connection(self):
        self.sftp_client.close()

    def backup_files(self, source_paths):
        if not self.connect():
            return False

        with self.sftp_client.open(f"{self.destination_path}/logs.txt", 'w') as file:
            file.write("Backup log\n")
        for source_path in source_paths:
            print(f"Backing up {source_path}")
            filename = self.create_backup(source_path)
            if filename:
                if not self.send_backup(filename):
                    return False
        self.close_connection()
        return True

