            ssh_client = self.connect_ssh(vm)
            if ssh_client:
                try:
                    self.run_test_suite(ssh_client, vm)
                    self.save_test_result(ssh_client, vm)
                    self.copy_output_files(ssh_client, vm)
                    self.change_permissions(vm)
                except CalledProcessError as e:
                    print(f"Error on {vm.vm_name} - {e}")
                finally:
                    ssh_client.close()

    def connect_ssh(self, vm):
        try:
            client = paramiko.SSHClient()
            client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
            client.connect(hostname=vm.hostname, username=vm.username, 
                          key_filename=vm.private_key, timeout=10)
            return client
        except NoValidConnectionsError:
            print(f"Failed to connect to {vm.vm_name}")
            return None

    def run_test_suite(self, client, vm):
        try:
            process = client.exec_command(command='pytest --junit-xml=/home/{}/results.xml'.format(vm.vm_name))
            stdout, stderr = process.readlines()
            print('Test result for {}: {}'.format(vm.vm_name, stdout))
        except CalledProcessError:
            print(f"Failed to run test suite on {vm.vm_name}")

    def save_test_result(self, client, vm):
