        with open(os.path.join(self.output_dir, vm.vm_name,'results.xml'), 'w') as f:
            f.write(remote_output)

    def copy_output_files(self, client, vm):
        sftp_client = client.get_transport().open_sftp()
        for f in ['results.xml', 'output.log', 'html_report/index.html']:
            remote_file_path = '/home/{}/{}'.format(vm.vm_name, f)
            remote_file = sftp_client.open(remote_file_path)
            local_file_path = os.path.join(self.output_dir, vm.vm_name, f)
            try:
                local_dir = os.path.dirname(local_file_path)
                os.makedirs(local_dir, exist_ok=True)
                with open(local_file_path, 'wb') as local_file:
                    local_file.write(remote_file.read())
            except (OSError, IOError) as e:
                print(f"Error copying file {local_file_path}: {e}")
            finally:
                remote_file.close()
                sftp_client.close()

    def change_permissions(self, vm):
        for perm in self.permissions.get(vm.vm_name, []):
            print(f"Change permissions of {perm} on {vm.vm_name} to {self.permissions[vm.vm_name][perm]}")
