                print(f"Branch switched to {self.branch}")
            except git.InvalidGitReferenceError:
                print("Invalid branch specified")

    def pull_repo(self):
        try:
            self.repo.remotes.origin.fetch()
            self.repo.git.reset('--hard', self.branch)
            print("Repository pulled from remote")
        except git.InvalidGitRepositoryError:
            print("Invalid repository location")

    def deploy(self):
        command = f"git ls-files -z | xargs -0 scp -r -T {self.dest_dir}/:/remote/path"
        try:
            subprocess.run(command, check=True, shell=True)
            print("Repository deployed to remote server")
