import os
import hashlib
import shutil
import argparse
from datetime import datetime
from pathlib import Path

class FileSyncer:
    def __init__(self, src_dir, dest_dir):
        self.src_dir = Path(src_dir)
        self.dest_dir = Path(dest_dir)

    def hash_file(self, file_path):
        with open(file_path, 'rb') as f:
            md5 = hashlib.md5()
            while chunk := f.read(4096):
                md5.update(chunk)
        return md5.hexdigest()

    def check_sync(self):
        for src_file in self.src_dir.glob('**/*'):
            if not src_file.is_file():
                continue
            dest_file = self.dest_dir / src_file.relative_to(self.src_dir)
            if not dest_file.parent.exists():
                dest_file.parent.mkdir(parents=True, exist_ok=True)
            src_hash = self.hash_file(src_file)
            if dest_file.exists():
                dest_hash = self.hash_file(dest_file)
                if src_hash!= dest_hash:
                    print(f"Hash mismatch: {src_file} - {src_hash}!= {dest_hash}")
                    dest_file.unlink()
                    shutil.copy2(src_file, dest_file)
            else:
                shutil.copy2(src_file, dest_file)

    def sync_files(self):
        for dest_file in self.dest_dir.glob('**/*'):
            if not dest_file.is_file():
                continue
            src_file = self.src_dir / dest_file.relative_to(self.dest_dir)
            if not src_file.exists():
                print(f"Removed {dest_file} as it no longer exists")
                dest_file.unlink()
            elif src_file.stat().st_mtime > dest_file.stat().st_mtime:
                shutil.copy2(src_file, dest_file)

def main():
    parser = argparse.ArgumentParser(description='File Synchronizer')
    parser.add_argument('--src', help='Source directory', required=True)
    parser.add_argument('--dest', help='Destination directory', required=True)
    args = parser.parse_args()

    syncer = FileSyncer(args.src, args.dest)
    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    print(f"Started file synchronization at: {now}")
    syncer.check_sync()
    syncer.sync_files()
    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    print(f"Finished file synchronization at: {now}")

if __name__ == "__main__":
    main()
