class FileSync:
    def __init__(self, local_dir, remote_dir, remote_host):
        self.local_dir = local_dir
        self.remote_dir = remote_dir
        self.remote_host = remote_host

    def sync_files(self):
        try:
            # Copy files from local to remote
            with ssh_client(self.remote_host) as client:
                for filename in os.listdir(self.local_dir):
                    local_file_path = os.path.join(self.local_dir, filename)
                    remote_file_path = os.path.join(self.remote_dir, filename)
                    if os.path.isfile(local_file_path) and not self.file_exists_on_remote(client, remote_file_path):
                        logging.info(f'Uploading {filename}')
                        client.sftp.put(local_file_path, remote_file_path)
                    elif os.path.isdir(local_file_path) and not self.dir_exists_on_remote(client, remote_file_path):
                        logging.info(f'Uploading directory {filename}')
                        client.sftp.mkdir(remote_file_path)
                        self.sync_dir(client, remote_file_path, local_file_path)
                # Copy files from remote to local
                for filename in os.listdir(self.remote_dir):
                    remote_file_path = os.path.join(self.remote_dir, filename)
                    local_file_path = os.path.join(self.local_dir, filename)
                    if os.path.isfile(remote_file_path) and not self.file_exists_on_local(local_file_path):
                        logging.info(f'Downloading {filename}')
                        client.sftp.get(remote_file_path, local_file_path)
                    elif os.path.isdir(remote_file_path) and not self.dir_exists_on_local(local_file_path):
                        logging.info(f'Downloading directory {filename}')
                        client.sftp.mkdir(local_file_path)
                        self.sync_dir(client, local_file_path, remote_file_path)
        except Exception as e:
            logging.error(f'Error synchronizing files: {e}')

    def sync_dir(self, client, remote_dir, local_dir):
        for filename in os.listdir(remote_dir):
            remote_file_path = os.path.join(remote_dir, filename)
            local_file_path = os.path.join(local_dir, filename)
            if os.path.isfile(remote_file_path):
                if not self.file_exists_on_local(local_file_path):
                    logging.info(f'Downloading file {filename}')
                    client.sftp.get(remote_file_path, local_file_path)
            elif os.path.isdir(remote_file_path):
                if not self.dir_exists_on_local(local_file_path):
                    logging.info(f'Downloading directory {filename}')
                    client.sftp.mkdir(local_file_path)
                    self.sync_dir(client, local_file_path, remote_file_path)

    def file_exists_on_remote(self, client, file_path):
        try:
            client.sftp.stat(file_path)
            return True
        except IOError:
            return False

    def dir_exists_on_remote(self, client, dir_path):
        try:
            client.sftp.stat(dir_path)
            return True
        except IOError:
            return False

    def file_exists_on_local(self, file_path):
        return os.path.exists(file_path)

    def dir_exists_on_local(self, dir_path):
        return os.path.exists(dir_path)

def ssh_client(host):
    import paramiko
    ssh = paramiko.SSHClient()
    ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
    ssh.connect(host, username='username', password='password')
    return ssh

def main():
